def _hh_render_status(message,error=False):
    global _hh_status_error_until
    now=_time.monotonic()
    if not error and now<_hh_status_error_until:return
    if error:_hh_status_error_until=now+15
    text=_hh_re.sub(r'<[^>]*>','',str(message))
    text=_hh_translate(text)
    plain=''.join(c for c in _hh_unicode.normalize('NFKD',text) if not _hh_unicode.combining(c)).lower().replace('đ','d')
    parts=_hh_re.split(r'(?i)cách (?:xử lý|khắc phục):',text,maxsplit=1)
    status=parts[0].strip()
    if len(parts)>1:help_text=parts[1].strip()
    elif 'ready' in plain:
        help_text='Kiểm tra acc đang chờ trong Party và đúng Leader; cần gọi tay thì Leader gõ !pha <số>.'
    elif '10m' in plain or '10 m' in plain:
        help_text='Đưa Bảo tiêu được nêu về cách Leader không quá 10 m; không cần xác nhận lại vai trò.'
    elif 'npc' in plain or 'ben' in plain or 'pha' in plain:
        help_text='Đến đúng NPC tại bến, đóng cửa sổ NPC; Leader gõ !pha <số> để gọi tay hoặc bấm Tiếp tục.'
    elif 'ban' in plain or 'mua' in plain:
        help_text='Kiểm tra NPC, túi hàng và thú; chờ giao dịch hoàn tất trước khi Tiếp tục.'
    elif 'dung' in plain or 'loi' in plain or 'that bai' in plain:
        help_text='Xem lý do trong nhật ký; xử lý xong bấm Tiếp tục, không đổi Bước khi giao dịch còn dở.'
    else:help_text='Theo dõi trạng thái; khi chủ động dừng, bấm Tiếp tục để chạy tiếp.'
    _qt.setText(gui,_hh_status_row,'Trạng thái: '+(status[12:] if status.startswith('Trạng thái: ') else status))
    _qt.setText(gui,_hh_help_row,'Xử lý: '+help_text)


def _hh_retire_stale(module):
    # Cached callbacks may survive deleting/reloading a plugin file. Disable the
    # old namespaces without issuing STOP or touching the current SDK sender.
    module.__dict__['_hh_retired'] = True
    def idle(*args, **kwargs):return True
    for old in module.__dict__.get('_hh_modules', {}).values():
        for name, value in list(vars(old).items()):
            if callable(value) and getattr(value, '__module__', None)==old.__name__:
                setattr(old, name, idle)
    for name in ('event_loop','handle_chat','handle_joymax','handle_silkroad','handle_event','teleported','disconnected'):
        module.__dict__[name]=idle


def _hh_trade_gate(report=False):
    if globals().get('_hh_retired'):return False
    others=[]
    own=_hh_modules.get('caravan')
    own_path=_os.path.normcase(_os.path.realpath(__file__))
    for module in list(_sys.modules.values()):
        if not isinstance(module,_types.ModuleType):continue
        data=module.__dict__
        foreign=data.get('_hh_caravan')
        if foreign is None or foreign is own or data.get('_hh_retired'):continue
        if not callable(getattr(foreign,'route_ferry_tick',None)):continue
        path=data.get('__file__')
        # Only a real deleted file or an earlier load of this exact file is stale.
        if path and (_os.path.normcase(_os.path.realpath(path))==own_path or
                     (_os.path.isabs(path) and not _os.path.exists(path))):
            _hh_retire_stale(module)
            pass  # Stale-cache cleanup is routine; no progress log.
            continue
        label=_os.path.basename(str(path or '?'))
        if label not in others:others.append(label)
    if not others:return True
    signature=tuple(sorted(others))
    if report or _hh_hook_errors.get(('duplicate_trade',))!=signature:
        _hh_hook_errors[('duplicate_trade',)]=signature
        _hh_error_log('[AutoBuonHoangHiep] CHƯA CHẠY: còn bản AutoBuôn khác đang nạp: '+', '.join(signature)+'. Giữ một file AutoBuôn, sau đó nạp lại plugin hoặc khởi động lại phBot.')
    return False


