def case(old,new):
 if old.isupper():return new.upper()
 if old[:1].isupper():return new[:1].upper()+new[1:]
 return new
def translate(text):
 # Protect technical identifiers, paths and placeholder contents before word restoration.
 protected={}
 def protect(m):
  key='§'+str(len(protected))+'§';protected[key]=m.group();return key
 text=re.sub(r'\{[^}]*\}|0x[0-9A-Fa-f]+|![A-Za-z0-9_]+|\b[\w]+_[\w.]+\b|\b[\w.]+\.(?:txt|json|py|dll|exe|bak)\b',protect,text)
 for a,b in sorted(phrases.items(),key=lambda x:-len(x[0])):
  text=re.sub(re.escape(a),lambda m:case(m.group(),b),text,flags=re.I)
 def word(m):
  w=m.group()
  if w in reserved or not w.isascii():return w
  return case(w,words.get(w.lower(),w))
 text=re.sub(r'\b[^\W\d_]+\b',word,text,flags=re.UNICODE)
 for key,value in protected.items():text=text.replace(key,value)
 return text

_hh_translate=translate
# This proxy is local to bundled engines. The global phBot module/senders are untouched.
import re as _hh_re
import unicodedata as _hh_unicode
_hh_error_times={}

def _hh_error_log(message,force=False):
    text=str(message)
    text=_hh_re.sub(r'^\[[^\]]+\]\s*','',text)
    plain=''.join(c for c in _hh_unicode.normalize('NFKD',text) if not _hh_unicode.combining(c)).lower().replace('đ','d')
    routine=('npc: lenh phbot da dung','dang qua pha: tam hoan','npc selected','da chon npc','teleport request sent','da gui yeu cau dich chuyen','ca doi da xac nhan','ready pha tu')
    blocking=('dang giu mot luot pha','dung tai pha','dang ghi pha thu cong','khong co cau hinh ma pha','qua pha dang cho hoi')
    force=force or plain.startswith(blocking)
    error_pattern=r'(loi|that bai|failed|cannot|invalid|unknown|cancelled|timeout|exception|chua (?:goi|nhan|xoa|gui|chay|bat|the|ban|mua|xac|co|thay|ready)|chua bat|chua thay|chua co toa do|chua xac minh|chua chay|khong the|khong gui duoc|khong doc duoc|khong tim thay|khong con trong party|khong hop le|khong duoc phep|khong co thu|khong nhan lenh|bi tu choi|mat ket noi|het \d+\s*s|qua \d+\s*s|khoi lenh.*do|chua ban duoc|khong cho phep|sai nhan vat)'
    if not force and (plain.startswith(routine) or not _hh_re.search(error_pattern,plain)):return
    # Preserve actual character and NPC names when adding Vietnamese accents.
    names=set()
    try:
        rows=[_bot.get_character_data() or {}]
        for getter in ('get_party','get_npcs'):
            data=getattr(_bot,getter,lambda:{})() or {}
            if isinstance(data,dict):rows.extend(x for x in data.values() if isinstance(x,dict))
        for row in rows:
            names.update(str(row.get(k)) for k in ('name','job_name') if row.get(k))
    except Exception:pass
    preserved={}
    for name in sorted(names,key=len,reverse=True):
        if len(name)<2:continue
        marker='↯'+str(len(preserved))+'↯'
        revised=_hh_re.sub(r'(?<!\w)'+_hh_re.escape(name)+r'(?!\w)',lambda m:marker,text)
        if revised!=text:preserved[marker]=name;text=revised
    text=_hh_translate(text)
    for marker,name in preserved.items():text=text.replace(marker,name)
    ferry_status=any(marker in plain for marker in ('san sang: da gui party','leader da nhan san sang','pha: da gui party','du san sang luot','pha rx party:'))
    if not ferry_status and 'cach xu ly:' not in plain and 'xu ly:' not in plain:
        if 'khoi lenh' in plain:
            text+=' Cách xử lý: kiểm tra lệnh đang dở; chỉ nhập bước sau khi đã xác nhận lệnh đó hoàn tất.'
        elif 'pha' in plain:
            text+=' Cách xử lý: kiểm tra đúng bến/NPC, Party và Leader đã lưu; đọc lý do trên acc còn thiếu rồi bấm Tiếp tục.'
        elif 'ban' in plain or 'npc' in plain or 'giao dich' in plain:
            text+=' Cách xử lý: kiểm tra NPC và túi hàng trên acc báo lỗi; không bỏ qua giao dịch khi còn hàng.'
        elif 'hen gio' in plain or 'lich' in plain:
            text+=' Cách xử lý: kiểm tra ngày/giờ máy, giờ kết thúc, hướng đã tích và danh sách đoàn rồi lưu lại.'
        else:text+=' Cách xử lý: kiểm tra trạng thái nhân vật và cấu hình đang dùng; xử lý xong mới bấm Tiếp tục.'
    now=_time.monotonic()
    if now-_hh_error_times.get(text,float('-inf'))<2:return
    if len(_hh_error_times)>512:_hh_error_times.clear()
    _hh_error_times[text]=now
    try:
        who=_bot.get_character_data() or {}
        caravan=_hh_modules.get('caravan')
        cfg=getattr(caravan,'config',None) or {}
        role='Bảo tiêu' if cfg.get('hunter') else 'Buôn phụ' if cfg.get('follower') else 'Leader/acc buôn'
        if who.get('name'):text=str(who['name'])+' ['+role+'] · '+text
    except Exception:pass
    _hh_render_status(text,error=True)
    _bot.log('[AutoBuonHoangHiep] '+text)

class _hh_BotProxy:
    def __getattr__(self,name):
        return _hh_error_log if name=='log' else getattr(_bot,name)
_hh_bot_proxy=_hh_BotProxy()


def _hh_load(page, source):
    panel = _Panel(page)
    _hh_panels[page] = panel
    module = _types.ModuleType(__name__ + '_' + page)
    module.__file__ = __file__
    module.__dict__['_hh_qt'] = panel
    module.__dict__['_hh_error_log']=_hh_error_log
    module.__dict__['_hh_translate']=_hh_translate
    module.__dict__['_hh_bot_proxy']=_hh_bot_proxy
    module.__dict__['_hh_trade_gate'] = _hh_trade_gate
    module.__dict__['_hh_render_status'] = _hh_render_status
    if page in ('guard', 'ferry', 'rules', 'schedule'):
        module.__dict__['caravan'] = _hh_modules['caravan']
    _hh_modules[page] = module
    _sys.modules[module.__name__] = module
    # Only replace this explicit module import; phBot imports keep their original behavior.
    source = source.replace('import QtBind\n', 'QtBind = _hh_qt\n')
    source=source.replace('import phBot as bot\n','bot = _hh_bot_proxy\n').replace('from phBot import *\n','from phBot import *\nlog = _hh_error_log\n')
    source=_hh_re.sub(r'(?m)^(from phBot import [^\n]+)$',lambda match:match.group(0)+'\nlog = _hh_error_log',source)
    exec(compile(source, __file__ + ':' + page, 'exec'), module.__dict__)
    module.__dict__['log']=_hh_error_log
    return module


