def item_group(item):
    # Prefer the game code, then use the display name for custom server items.
    for field_name in ('servername', 'name'):
        words = set(re.findall(r'[A-Z]+', (item.get(field_name) or '').upper()))
        for category, markers in ITEM_WORDS.items():
            if words & markers:
                return category
    return None


def refresh_item(force=False):
    global shown_item
    key = QtBind.text(gui, items)
    if force or key != shown_item:
        shown_item = key
        entry = scanned.get(key)
        show_group(entry[2] if entry else None)
        if entry and group == 'Quần áo' and entry[:2] in armor_stats:
            for row, percent in zip(rows, armor_stats[entry[:2]]):
                QtBind.setText(gui, row[1], str(percent))
            QtBind.setText(gui, status, 'Đã đọc chỉ số giáp từ dữ liệu túi.')
        elif entry and entry[1] == 4373:
            say('Chưa có % giáp 4373 ở ô {}. Gói 0x3013 đã nhận: {}; ô có dữ liệu: {}.'.format(
                entry[0] - 12, login_packets_seen,
                ', '.join(str(slot - 12) for slot, _ in armor_stats) or 'không có'))
        elif entry:
            message = ('{} · Nhập % hiện tại đọc trong game.'.format(entry[2])
                       if entry[2] else 'Chọn mục phù hợp rồi nhập % hiện tại trong game.')
            QtBind.setText(gui, status, message)


def say(message):
    QtBind.setText(gui, status, message)
    log('[SROMix] ' + message)


def inventory():
    return (get_inventory() or {}).get('items') or []


def scan():
    with lock:
        if job or pending:
            return
        QtBind.clear(gui, items)
        scanned.clear()
        wanted = QtBind.text(gui, item_filter).strip()
        for slot, item in enumerate(inventory()):
            if item and 13 <= slot <= 255 and (not wanted or str(item.get('model')) == wanted):
                model = item.get('model')
                key = 'Ô {} | {} | {}'.format(slot - 12, model, item.get('name', ''))
                scanned[key] = (slot, model, item_group(item))
                QtBind.append(gui, items, key)
        refresh_item(force=True)


def stop():
    global job, pending
    with lock:
        job = None
        if pending and pending['kind'] not in ('buy', 'mix'):
            pending = None
        say('Đã dừng gửi lệnh mới.')


def current_mix():
    if not job:
        return None
    return job if job['kind'] == 'mix' else job.get('next_mix')


def sync_mix_boxes():
    global syncing_mix_boxes
    mix = current_mix()
    paused = mix is not None and bool(mix.get('paused'))
    syncing_mix_boxes = True
    try:
        for box, desired in ((pause_box, paused), (resume_box, mix is not None and not paused)):
            if QtBind.isChecked(gui, box) != desired:
                QtBind.setChecked(gui, box, desired)
    finally:
        syncing_mix_boxes = False


def pause_mix(checked):
    with lock:
        if syncing_mix_boxes:
            return
        mix = current_mix()
        if checked and mix is not None and not mix.get('paused'):
            mix['paused'] = True
            say('Đã tạm dừng gửi lượt ép mới.')
        sync_mix_boxes()


def resume_mix(checked):
    with lock:
        if syncing_mix_boxes:
            return
        mix = current_mix()
        if checked and mix is not None and mix.get('paused'):
            mix['paused'] = False
            say('Đã tiếp tục lượt ép đang dở.')
        sync_mix_boxes()


def remember():
    with lock:
        position = get_position()
        if job or pending or not position or 'region' not in position:
            return
        points.append(position.copy())
        say('Đã thêm điểm ép số {} cho phiên này.'.format(len(points)))


def send(kind, opcode, payload, **state):
    global pending
    pending = dict(state, kind=kind, deadline=time.monotonic() + 12)
    inject_joymax(opcode, payload, False)


def buy():
    global job
    with lock:
        if pending or job:
            return
        try:
            queue, configured = table_orders()
        except ValueError as error:
            say(str(error))
            return
        if not queue:
            say('Túi đã đủ đá theo số lượng cài.' if configured else
                'Nhập số viên vào cột Mua trước khi bắt đầu.')
            return
        job = dict(kind='buy', uid=STONE_NPC_UID, queue=queue)
        say('Bắt đầu mua theo số lượng đã nhập.')


def start_mix():
    global job, selection, spent
    with lock:
        if pending or job:
            return
        refresh_item()
        entry = scanned.get(shown_item)
        checked = [index for index, row in enumerate(rows) if QtBind.isChecked(gui, row[0])]
        if not entry or not checked:
            say('Chọn đồ và tích ít nhất một dòng chỉ số để ép.')
            return
        slot, model, detected = entry
        if detected and detected != group:
            say('Chọn đúng mục {} cho món đồ này.'.format(detected))
            return
        try:
            queue, _ = table_orders()
        except ValueError as error:
            say(str(error))
            return
        try:
            limit = int(QtBind.text(gui, relocate_limit))
            if limit <= 0:
                raise ValueError
        except ValueError:
            say('Số lượng D/C phải là số nguyên lớn hơn 0.')
            return
        mix = dict(kind='mix', slot=slot, model=model, indices=checked, active=None, relocate_limit=limit)
        job = dict(kind='buy', uid=STONE_NPC_UID, queue=queue, next_mix=mix) if queue else mix
        if queue:
            say('Đang mua đá trong shop. Mua xong sẽ bắt đầu ép.')


def shop_file():
    return Path(get_config_dir()) / 'SROMix-stone-shop.json'


def shop_point():
    try:
        return json.loads(shop_file().read_text(encoding='utf-8'))
    except (OSError, ValueError):
        return {}


def nearby_shop(saved, position):
    for uid, npc_data in (get_npcs() or {}).items():
        if npc_data.get('region') != position.get('region'):
            continue
        if saved:
            matches = (npc_data.get('model') == saved['model']
                       and math.hypot(npc_data['x'] - saved['x'], npc_data['y'] - saved['y']) <= 15)
        else:
            matches = (uid == int.from_bytes(STONE_NPC_UID, 'little')
                       or (npc_data.get('name') or '').casefold() in
                       ('tạp hóa tổng hợp tất cả trong 1', 'tap hoa tong hop tat ca trong 1'))
        if matches:
            return uid, npc_data
    return None


def save_shop():
    with lock:
        if job or pending:
            return
        position = get_position() or {}
        found = nearby_shop({}, position)
        if not found or math.hypot(found[1]['x'] - position['x'],
                                   found[1]['y'] - position['y']) > 10:
            say('Đứng sát NPC Đá Mix rồi bấm Lưu điểm NPC đá.')
            return
        data = found[1]
        point = {key: data[key] for key in ('model', 'region', 'x', 'y')}
        try:
            shop_file().write_text(json.dumps(point), encoding='utf-8')
        except OSError as error:
            say('Không lưu được điểm NPC: {}'.format(error))
            return
        say('Đã lưu điểm NPC đá.')


def gate_file():
    return shop_file().with_name('SROMix-hoa-dien-gate.json')


def gate_point():
    try:
        return json.loads(gate_file().read_text(encoding='utf-8'))
    except (OSError, ValueError):
        return {}


def save_gate():
    with lock:
        if job or pending:
            return
        position = get_position() or {}
        gate = (get_npcs() or {}).get(9)
        if (not gate or gate.get('region') != position.get('region')
                or math.hypot(gate['x'] - position['x'], gate['y'] - position['y']) > 10):
            say('Đứng sát cổng Hòa Điền (UID 9 trong log) rồi bấm lưu.')
            return
        try:
            gate_file().write_text(json.dumps({key: gate[key] for key in
                                               ('model', 'region', 'x', 'y')}), encoding='utf-8')
        except OSError as error:
            say('Không lưu được cổng: {}'.format(error))
            return
        say('Đã lưu cổng Hòa Điền đi Đôn Hoàng.')


def approach_gate(position, gate):
    now = time.monotonic()
    if now >= job.setdefault('gate_deadline', now + 45):
        stop()
        say('Không đến được cổng Hòa Điền.')
        return
    for uid, npc_data in (get_npcs() or {}).items():
        if (npc_data.get('model') == gate['model'] and npc_data.get('region') == gate['region']
                and math.hypot(npc_data['x'] - gate['x'], npc_data['y'] - gate['y']) <= 10
                and math.hypot(npc_data['x'] - position['x'], npc_data['y'] - position['y']) <= 6):
            send('gate_select', 0x7045, struct.pack('<I', uid), uid=uid)
            return
    if now >= job.get('gate_move_at', 0):
        job['gate_move_at'] = now + 3
        move_to(gate['x'], gate['y'], 0)


def approach_shop():
    global pending
    position = get_position() or {}
    saved = shop_point()
    found = nearby_shop(saved, position)
    destination = found[1] if found else saved
    if not position or not destination:
        stop()
        say('Cần đăng nhập và lưu điểm NPC đá một lần trước khi mua.')
        return
    if destination['region'] != position.get('region'):
        gate = gate_point()
        if gate and gate['region'] == position.get('region') and not job.get('gate_used'):
            approach_gate(position, gate)
            return
        if job.get('shop_return_used') or job.get('gate_used'):
            stop()
            say('Bùa không đưa về khu NPC đá. Kiểm tra thành hồi hương.')
            return
        job['shop_return_used'] = True
        pending = dict(kind='shop_return', region=destination['region'],
                       deadline=time.monotonic() + 60, arrived=False)
        if use_return_scroll():
            say('Đang dùng bùa về thành có NPC đá.')
        else:
            pending = None
            stop()
            say('Không dùng được bùa về thành để đi mua đá.')
        return
    distance = math.hypot(destination['x'] - position['x'], destination['y'] - position['y'])
    if found and distance <= 6:
        job['uid'] = struct.pack('<I', found[0])
        if manual_shop_uid == job['uid']:
            shop_ready()
        else:
            say('Đã tới NPC. Đang tự mở shop Đá Mix.')
            send('shop_select', 0x7045, job['uid'])
        return
    now = time.monotonic()
    deadline = job.setdefault('shop_deadline', now + 45)
    if now >= deadline:
        stop()
        say('Không đến được NPC đá trong 45 giây.')
    elif now >= job.get('shop_move_at', 0):
        job['shop_move_at'] = now + 3
        move_to(destination['x'], destination['y'], destination.get('z', 0))


def stone_count(model, bag=None):
    if bag is None:
        bag = inventory()
    return sum(item.get('quantity', 0) for item in bag[13:]
               if item and item.get('model') == model
               and isinstance(item.get('quantity'), int))


def confirm_buy():
    global pending
    if job:
        job.setdefault('bought_models', set()).add(pending['model'])
        slot, remaining = job['queue'][0]
        remaining -= pending['quantity']
        if remaining:
            job['queue'][0] = (slot, remaining)
        else:
            job['queue'].pop(0)
    pending = None


def shop_ready():
    job['shop_open'] = True
    job['buy_ready_at'] = time.monotonic() + BUY_INTERVAL
    say('Shop đã mở. Bắt đầu mua theo từng lượt xác nhận.')


