def available_ep_points(position):
    region = position.get('region')
    candidates = [point for point in points if point['region'] == region]
    if region is None or not any(math.hypot(position['x'] - x, position['y'] - y) <= 60
                                 for x, y, _ in DON_HOANG_POINTS):
        return candidates
    z_now = position.get('z')
    candidates.extend(dict(x=x, y=y, z=z, town_route=True)
                      for x, y, z in DON_HOANG_POINTS
                      if z_now is None or abs(z_now - z) <= 100)
    return candidates


def start_point_walk(candidates, after_purchase=False):
    global pending
    candidates = list(candidates)
    random.shuffle(candidates)
    now = time.monotonic()
    pending = dict(kind='walk', point=candidates.pop(), alternatives=candidates,
                   move_at=now + 1, switch_at=now + 13, deadline=now + 45,
                   after_purchase=after_purchase)


def merge_bought_stones():
    stacks = {}
    for slot, item in enumerate(inventory()[13:256], 13):
        if not item or item.get('model') not in job['bought_models']:
            continue
        quantity = item.get('quantity')
        if isinstance(quantity, int) and 0 < quantity < 100:
            stacks.setdefault(item['model'], []).append((slot, quantity))
    for model, entries in stacks.items():
        if len(entries) < 2:
            continue
        entries.sort(key=lambda entry: (-entry[1], entry[0]))
        destination, count = entries[0]
        source, available = entries[-1]
        amount = min(100 - count, available)
        send('merge', 0x7034, struct.pack('<BBBH', 0, source, destination, amount),
             destination=destination, model=model, expected=count + amount)
        return True
    return False


def tick_buy():
    global job, pending
    if time.monotonic() < job.get('buy_ready_at', 0):
        return
    if not job['queue']:
        next_mix = job.get('next_mix')
        if not job.get('shop_closed'):
            send('shop_close', 0x704B, job['uid'])
            return
        if job.get('bought_models') and not job.get('merge_skipped') and merge_bought_stones():
            return
        job = next_mix
        if not job:
            say('Đã mua xong tất cả loại đá và đóng phiên NPC.')
            return
        position = get_position() or {}
        nearby = available_ep_points(position)
        if not nearby:
            job = None
            say('Đã mua xong và đóng NPC. Cần thêm điểm ép trong khu này.')
            return
        start_point_walk(nearby, after_purchase=True)
        say('Đã mua xong và đóng NPC. Đang đi tới điểm ép.')
        return
    if not job.get('shop_open'):
        approach_shop()
        return
    slot, remaining = job['queue'][0]
    quantity = min(100, remaining)
    data = struct.pack('<BBBH', 8, 3, slot, quantity) + job['uid']
    model = next(model for model, shop_slot in STONE_SHOP_SLOTS.items() if shop_slot == slot)
    before = stone_count(model)
    log('[SROMix] Gửi 0x7034: {}'.format(data.hex(' ').upper()))
    job['buy_ready_at'] = time.monotonic() + BUY_INTERVAL
    send('buy', 0x7034, data, slot=slot, quantity=quantity, model=model, before=before)


def finish_mix_row():
    QtBind.setChecked(gui, rows[job['indices'].pop(0)][0], False)
    job['active'] = None


def tick_mix():
    global pending, selection, spent, job
    bag = inventory()
    slot = job['slot']
    item = bag[slot] if slot < len(bag) else None
    if not item or item.get('model') != job['model']:
        stop()
        say('Món đồ đã đổi ô hoặc không đọc được.')
        return
    try:
        new_limit = int(QtBind.text(gui, relocate_limit))
    except ValueError:
        new_limit = 0
    if new_limit > 0 and new_limit != job['relocate_limit']:
        job['relocate_limit'] = new_limit
        say('Đã cập nhật mốc D/C thành {} viên.'.format(new_limit))
    while job['indices']:
        row = job['indices'][0]
        check, current, target = rows[row]
        stone_model = ROW_STONES[group][row]
        stone_slot = next((i for i, stone in enumerate(bag)
                           if 13 <= i <= 255 and i != slot and stone
                           and stone.get('model') == stone_model
                           and isinstance(stone.get('quantity'), int)
                           and stone['quantity'] > 0), None)
        key = (slot, job['model'], group, row, stone_model)
        limit = job['relocate_limit']
        due = key == selection and spent >= limit
        repeat = QtBind.isChecked(gui, repeat_mix)
        if not QtBind.isChecked(gui, check) or (stone_slot is None and not due and not repeat):
            if stone_slot is None and QtBind.isChecked(gui, check):
                say('Thiếu đá {} cho {}. Bỏ qua.'.format(stone_model, GROUPS[group][row]))
            finish_mix_row()
            continue
        if job['active'] is None:
            try:
                cached = armor_stats.get((slot, job['model'])) if group == 'Quần áo' else None
                current_text = QtBind.text(gui, current).strip()
                percent = cached[row] if cached is not None else (
                    int(current_text) if current_text else None)
                goal = int(QtBind.text(gui, target))
                if (goal not in (80, 100) or (percent is not None and not 0 <= percent <= 100)
                        or (percent is None and not QtBind.isChecked(gui, allow_unknown))):
                    raise ValueError
                if cached is not None:
                    QtBind.setText(gui, current, str(percent))
            except ValueError:
                job = None
                say('Thiếu % hiện tại hoặc mục tiêu 80/100 cho {}. Gói túi 0x3013 đã nhận: {}.'.format(
                    GROUPS[group][row], login_packets_seen))
                return
            if percent is None:
                say('Chưa biết % của {}. Ép thử để đọc kết quả.'.format(GROUPS[group][row]))
            elif percent >= goal:
                finish_mix_row()
                continue
            if key != selection:
                selection, spent = key, 0
            job.update(active=row, stone=stone_model, goal=goal)
        if due:
            pending = dict(kind='return', deadline=time.monotonic() + 45, arrived=False)
            if not use_return_scroll():
                pending = None
                stop()
                say('Không dùng được bùa về thành.')
            else:
                say('Đã tiêu {} viên, chưa đạt mục tiêu. Đang dùng bùa về thành.'.format(spent))
            return
        if stone_slot is None:
            try:
                queue, _ = table_orders()
            except ValueError as error:
                job['paused'] = True
                say(str(error))
                return
            if any(shop_slot == STONE_SHOP_SLOTS[stone_model] for shop_slot, _ in queue):
                job = dict(kind='buy', uid=STONE_NPC_UID, queue=queue, next_mix=job)
                say('Hết đá cho {}. Đang mua bù để ép tiếp.'.format(GROUPS[group][row]))
                return
            say('Thiếu đá {} và chưa cài số lượng mua cho loại này. Bỏ qua.'.format(stone_model))
            finish_mix_row()
            continue
        send('mix', 0x7151, bytes((2, 5, 2, slot, stone_slot)),
             slot=slot, stone=stone_slot, count=bag[stone_slot]['quantity'], result=None)
        return
    job = None
    say('Đã xét hết các dòng được tích.')


def teleported():
    global manual_shop_request, manual_shop_uid
    with lock:
        manual_shop_request = manual_shop_uid = None
        if pending and pending['kind'] in ('return', 'shop_return', 'shop_gate'):
            pending['arrived'] = True


def disconnected():
    global pending, job, armor_update, login_packets_seen, manual_shop_request, manual_shop_uid
    with lock:
        manual_shop_request = manual_shop_uid = None
        pending = job = armor_update = None
        login_packets_seen = 0
        armor_stats.clear()


def event_loop():
    global pending, job, spent, armor_update
    with lock:
        sync_mix_boxes()
        if pending:
            if pending['kind'] == 'buy' and job:
                gained = stone_count(pending['model']) - pending['before']
                if gained == pending['quantity']:
                    say('Đã nhận {} viên đá ID {}.'.format(gained, pending['model']))
                    confirm_buy()
                    return
            if pending['kind'] == 'merge' and job:
                bag = inventory()
                slot = pending['destination']
                item = bag[slot] if slot < len(bag) else None
                if item and item.get('model') == pending['model'] and item.get('quantity') == pending['expected']:
                    pending = None
                    return
                if time.monotonic() >= pending['deadline']:
                    job['merge_skipped'] = True
                    pending = None
                    say('Chưa xác nhận gộp đá. Tiếp tục với các chồng hiện có.')
                    return
            if time.monotonic() >= pending['deadline']:
                stage = pending['kind']
                active_job = job
                if stage == 'buy' and active_job:
                    response = pending.get('response', 'không có')
                pending = job = None
                if not active_job:
                    return
                if stage in ('gate_select', 'shop_gate'):
                    say('Chưa xác nhận được tuyến cổng Hòa Điền → Đôn Hoàng.')
                elif stage == 'shop_return':
                    say('Chưa về được khu NPC đá sau 60 giây. Kiểm tra thành hồi hương.')
                elif stage in ('shop_select', 'shop_open'):
                    say('Chưa nhận xác nhận chọn hoặc mở NPC Đá Mix.')
                elif stage == 'shop_close':
                    say('Hết thời gian chờ đóng shop.')
                elif stage == 'walk':
                    say('Không tới được điểm ép trong 45 giây.')
                elif stage == 'buy':
                    slot, remaining = active_job['queue'][0]
                    say('Ô shop {:02X}: chưa xác nhận mua, túi tăng {} viên, còn {} viên trong đơn. B034: {}.'.format(slot, gained, remaining, response))
                else:
                    say('Quá thời gian xác nhận. Kiểm tra túi trước khi chạy lại.')
                return
            if pending['kind'] in ('shop_return', 'shop_gate'):
                if not job:
                    pending = None
                elif pending['arrived']:
                    position = get_position() or {}
                    region = position.get('region')
                    gate = gate_point() if pending['kind'] == 'shop_return' else {}
                    if gate and region == gate['region']:
                        pending = None
                        say('Đã về Hòa Điền. Đang tới cổng đi Đôn Hoàng.')
                    elif region == pending['region']:
                        pending = None
                        say('Đã về đúng khu. Đang đi tới NPC đá.')
                    else:
                        check_after = pending.setdefault('check_after', time.monotonic() + 5)
                        if time.monotonic() >= check_after:
                            pending = job = None
                            say('Bùa về thành đã đưa tới khu khác NPC đá. Kiểm tra thành hồi hương.')
                return
            if pending['kind'] == 'mix' and pending['result'] is not None:
                bag = inventory()
                slot = pending['stone']
                if slot >= len(bag):
                    return
                item = bag[slot]
                if item and job and item.get('model') != job['stone']:
                    pending = job = None
                    say('Ô đá đổi loại trong lúc ép. Kiểm tra túi.')
                    return
                count = item.get('quantity') if item else 0
                if count != pending['count'] - 1:
                    return
                spent += 1
                changed = pending['result']
                decoded = pending.get('armor_percentages')
                pending = None
                if changed and job and decoded is not None:
                    row = job['active']
                    percent = decoded[row]
                    name = GROUPS[group][row]
                    for widgets, value in zip(rows, decoded):
                        QtBind.setText(gui, widgets[1], str(value))
                    armor_update = None
                    if percent >= job['goal']:
                        finish_mix_row()
                        say('{} đạt {}% sau {} viên. Xét dòng tiếp theo.'.format(name, percent, spent))
                    else:
                        say('{} {}%, mục tiêu {}%. Tiếp tục ép.'.format(name, percent, job['goal']))
                    return
                if changed:
                    job = None
                    for group_rows in rows_by_group.values():
                        for _, percent, _ in group_rows:
                            QtBind.setText(gui, percent, '')
                    say('Đã tiêu {} viên. Đọc lại % rồi bấm Bắt đầu mua / ép.'.format(spent))
                return
            if pending['kind'] == 'return' and pending['arrived']:
                position = get_position() or {}
                nearby = available_ep_points(position)
                if not job or not nearby:
                    pending = job = None
                    say('Đã dịch chuyển. Cần điểm ép đã lưu trong khu hiện tại.')
                    return
                start_point_walk(nearby)
            elif pending['kind'] == 'walk' and job:
                position = get_position() or {}
                point = pending['point']
                same_area = bool(position) and (point.get('town_route')
                                                or position.get('region') == point.get('region'))
                if same_area and math.hypot(
                        position['x'] - point['x'], position['y'] - point['y']) <= 4:
                    after_purchase = pending.get('after_purchase')
                    pending = None
                    if not after_purchase:
                        spent = 0
                    say('Đã tới điểm ép. Bắt đầu ép.' if after_purchase else 'Đã tới điểm ép mới.')
                elif same_area:
                    now = time.monotonic()
                    if pending['alternatives'] and now >= pending['switch_at']:
                        point = pending['point'] = pending['alternatives'].pop()
                        pending['switch_at'] = now + 12
                        pending['move_at'] = now
                        say('Chưa tới điểm ép. Đang thử điểm đã lưu khác.')
                    if now >= pending['move_at']:
                        pending['move_at'] = now + 3
                        move_to(point['x'], point['y'], point.get('z', 0))
            return
        if not job:
            refresh_item()
            show_armor_update()
        if job:
            if job['kind'] == 'buy':
                tick_buy()
            elif not job.get('paused'):
                tick_mix()


ARMOR_MODEL = 4373
ARMOR_RECORD = ARMOR_MODEL.to_bytes(4, 'little')


VARIANCE_OFFSETS = {
    'Quần áo': (15, 20, 25, 5, 10),
    'Khiên': (20, 25, 15, 5, 10),
    'Vũ khí': (20, 25, 15, 30, 5, 10),
}


def item_percentages(variance_bytes, category):
    value = int.from_bytes(variance_bytes, 'little')
    return tuple(((value >> offset) & 31) * 100 // 31
                 for offset in VARIANCE_OFFSETS[category])


def armor_percentages(variance_bytes):
    return item_percentages(variance_bytes, 'Quần áo')


def read_login_armor(data):
    # The captured inventory record is slot, rental type (0), model, plus, variance.
    offset = data.find(ARMOR_RECORD, 5)
    while offset >= 0:
        slot = data[offset - 5]
        if (13 <= slot <= 255 and data[offset - 4:offset] == bytes(4)
                and offset + 13 <= len(data)):
            armor_stats[(slot, ARMOR_MODEL)] = armor_percentages(data[offset + 5:offset + 13])
        offset = data.find(ARMOR_RECORD, offset + 4)


def decode_armor_parry(data):
    if len(data) < 25 or data[:3] != b'\x01\x02\x01' or data[8:12] != ARMOR_RECORD:
        return None
    return data[3], ARMOR_MODEL, armor_percentages(data[13:21])[2]


def show_armor_update():
    global armor_update
    if armor_update is None:
        return
    slot, model, percent = armor_update
    armor_update = None
    entry = scanned.get(shown_item)
    if group != 'Quần áo' or not entry or entry[:2] != (slot, model):
        return
    bag = inventory()
    if slot < len(bag) and bag[slot] and bag[slot].get('model') == model:
        QtBind.setText(gui, rows[2][1], str(percent))
        say('Tỉ lệ đỡ đọc từ kết quả ép: {}%.'.format(percent))


def handle_silkroad(opcode, data):
    global manual_shop_request, manual_shop_uid
    with lock:
        if opcode == 0x7046 and len(data) == 5 and data[4] == 1:
            manual_shop_request = bytes(data[:4])
            manual_shop_uid = None
        elif opcode == 0x704B:
            manual_shop_request = manual_shop_uid = None
    return True


def handle_joymax(opcode, data):
    global pending, job, armor_update, login_packets_seen, manual_shop_request, manual_shop_uid
    with lock:
        if opcode == 0xB046 and manual_shop_request is not None:
            manual_shop_uid = manual_shop_request if data[:2] == b'\x01\x01' else None
            manual_shop_request = None
        elif opcode == 0xB04B and data[:1] == b'\x01':
            manual_shop_uid = None
        if opcode == 0x34A5:
            login_packets_seen = 0
            armor_stats.clear()
        elif opcode == 0xB034 and data[:2] == b'\x01\x00':
            if len(data) >= 4:
                for slot in data[2:4]:
                    armor_stats.pop((slot, ARMOR_MODEL), None)
            else:
                armor_stats.clear()
        elif opcode == 0x3013:
            login_packets_seen += 1
            read_login_armor(data)
        elif opcode == 0xB151:
            result = decode_armor_parry(data)
            if result is not None:
                armor_update = result
                armor_stats[result[:2]] = armor_percentages(data[13:21])
        if not pending:
            return True
        if opcode == 0xB045 and pending['kind'] == 'shop_select':
            if job and data[:5] == b'\x01' + job['uid']:
                pending = dict(kind='shop_open', deadline=time.monotonic() + 12)
                inject_joymax(0x704B, job['uid'], False)
                inject_joymax(0x7046, job['uid'] + b'\x01', False)
        elif opcode == 0xB046 and pending['kind'] == 'shop_open':
            pending = None
            if job and data[:2] == b'\x01\x01':
                shop_ready()
            elif job:
                job = None
                say('NPC từ chối mở shop Đá Mix.')
        elif opcode == 0xB045 and pending['kind'] == 'gate_select':
            uid = struct.pack('<I', pending['uid'])
            if job and data[:5] == b'\x01' + uid:
                job['gate_used'] = True
                pending = dict(kind='shop_gate', region=shop_point()['region'],
                               deadline=time.monotonic() + 45, arrived=False)
                inject_joymax(0x705A, uid + struct.pack('<BI', 2, 2), False)
                say('Đang qua cổng Hòa Điền → Đôn Hoàng.')
        elif opcode == 0xB04B and pending['kind'] == 'shop_close':
            pending = None
            if job and data[:1] == b'\x01':
                job['shop_closed'] = True
            elif job:
                job = None
                say('NPC từ chối đóng shop.')
        elif opcode == 0xB034 and pending['kind'] == 'buy':
            expected = bytes((1, 8, 3, pending['slot'], pending['quantity']))
            if data[:5] == expected:
                confirm_buy()
            elif data[:3] == b'\x01\x08\x03' or data[:1] == b'\x02':
                pending['response'] = data.hex(' ').upper()
        elif opcode == 0xB151 and pending['kind'] == 'mix':
            if data[:4] == bytes((1, 2, 1, pending['slot'])):
                pending['result'] = True
                if (job and len(data) >= 25
                        and int.from_bytes(data[8:12], 'little') == job['model']):
                    pending['armor_percentages'] = item_percentages(data[13:21], group)
            elif data == bytes.fromhex('02 23 54'):
                pending['result'] = False
            else:
                pending = job = None
                say('Phản hồi ép chưa nhận diện. Kiểm tra món đồ và túi đá.')
    return True


