_hh_load('ferry', "import QtBind\nimport phBot as bot\nimport time\n\npanel = QtBind.init(__name__, 'Dò mã phà')\nQtBind.createLabel(panel, 'Chọn số phà → Bắt đầu ghi → tự qua phà trong game → Lưu mã sau khi đến nơi.', 12, 36)\nQtBind.createLabel(panel, 'Phà:', 12, 66)\nslot = QtBind.createCombobox(panel, 48, 62, 60, 20)\nfor number in range(1, 9):\n    QtBind.append(panel, slot, str(number))\nQtBind.setText(panel, slot, '1')\nQtBind.createButton(panel, 'start', 'Bắt đầu ghi', 125, 61)\nQtBind.createButton(panel, 'stop', 'Dừng ghi', 245, 61)\nQtBind.createButton(panel, 'save', 'Lưu mã', 350, 61)\nQtBind.createButton(panel, 'refresh', 'Nạp bảng', 450, 61)\nQtBind.createLabel(panel, 'NPC nguồn', 12, 96)\nnpc_box = QtBind.createLineEdit(panel, '', 98, 92, 310, 20)\nQtBind.createLabel(panel, 'Model', 420, 96)\nmodel_box = QtBind.createLineEdit(panel, '', 465, 92, 100, 20)\nQtBind.createLabel(panel, 'Mã đích', 575, 96)\ndest_box = QtBind.createLineEdit(panel, '', 628, 92, 100, 20)\nrows = QtBind.createList(panel, 12, 122, 716, 136)\nstatus_box = QtBind.createLabel(panel, 'Chưa ghi. Mỗi chiều qua phà lưu thành một số riêng.', 12, 266)\narmed = False\nowner = None\nrecord = None\nnpcs = {}\nrecord_slot = None\nstarted = 0\n\ndef status(message):\n    QtBind.setText(panel, status_box, message)\n    bot.log('[Dò mã phà] ' + message)\n\ndef refresh():\n    caravan.ferry_event_loop()\n    QtBind.clear(panel, rows)\n    routes = (caravan.ferry_settings or {}).get('routes', {})\n    for number in range(1, 9):\n        route = routes.get(str(number))\n        text = ('%s | Model=%s | Đích=%s' % (route.get('npc', ''), route.get('model'), route.get('destination'))) if route else 'Chưa lưu'\n        QtBind.append(panel, rows, 'Phà %d | %s' % (number, text))\n\ndef start():\n    global armed, owner, record, npcs, record_slot, started\n    caravan.ferry_event_loop()\n    key = caravan.ferry_config_identity()\n    if not key:\n        status('Hãy đăng nhập nhân vật trước khi ghi.')\n        return\n    if caravan.ferry_pending:\n        status('Chờ lượt qua phà tự động kết thúc trước khi ghi tay.')\n        return\n    number = QtBind.text(panel, slot).strip()\n    if number not in [str(i) for i in range(1, 9)]:\n        status('Chọn số phà từ 1 đến 8.')\n        return\n    armed, owner, record, record_slot = True, key, None, number\n    npcs = dict(bot.get_npcs() or {})\n    started = time.monotonic()\n    for widget in (npc_box, model_box, dest_box):\n        QtBind.setText(panel, widget, '')\n    status('Đang ghi phà %s: tự mở NPC và chọn qua phà trong game.' % number)\n\ndef stop():\n    global armed\n    armed = False\n    status('Đã dừng ghi; mẫu đã nhận vẫn có thể lưu sau khi đến nơi.')\n\ndef event_loop():\n    global armed, record, owner\n    key = caravan.ferry_config_identity()\n    if owner is not None and key != owner:\n        armed, record, owner = False, None, None\n        for widget in (npc_box, model_box, dest_box):\n            QtBind.setText(panel, widget, '')\n        status('Đổi nhân vật/mất kết nối: hủy mẫu chưa lưu, hãy ghi lại.')\n    if armed:\n        npcs.update(bot.get_npcs() or {})\n        if time.monotonic() - started > 180:\n            armed = False\n            status('Hết 180 giây chưa nhận gói qua phà. Bấm Bắt đầu ghi để thử lại.')\n\ndef handle_silkroad(opcode, data):\n    global armed, record\n    if not armed or opcode != 0x705A or owner != caravan.ferry_config_identity():\n        return True\n    try:\n        uid, destination = caravan.ferry_parse_ferry_packet(data)\n        npcs.update(bot.get_npcs() or {})\n        npc = npcs.get(uid) or npcs.get(str(uid))\n        if not isinstance(npc, dict) or not npc.get('model'):\n            status('Nhận mã đích nhưng thiếu NPC nguồn; đến gần NPC rồi ghi lại.')\n            return True\n        model = caravan.ferry_uint32(npc['model'])\n        record = dict(npc=str(npc.get('name') or ''), model=model, destination=destination)\n        armed = False\n        QtBind.setText(panel, npc_box, record['npc'])\n        QtBind.setText(panel, model_box, str(model))\n        QtBind.setText(panel, dest_box, str(destination))\n        status('Đã nhận phà %s · NPC UID=%s. Khi đến đúng bờ, bấm Lưu mã.' % (record_slot, uid))\n    except (ValueError, TypeError) as error:\n        status('Không đọc được gói qua phà: ' + str(error))\n    return True\n\ndef save():\n    if not record or owner != caravan.ferry_config_identity():\n        status('Chưa có mẫu hợp lệ. Bấm Bắt đầu ghi rồi tự qua phà.')\n        return\n    number = QtBind.text(panel, slot).strip()\n    if number != record_slot:\n        status('Mẫu này đã ghi cho phà %s. Chọn lại số đó để lưu.' % record_slot)\n        return\n    try:\n        caravan.ferry_event_loop()\n        route = dict(command='!pha ' + number, npc=QtBind.text(panel, npc_box).strip(),\n                     model=caravan.ferry_uint32(QtBind.text(panel, model_box).strip()),\n                     destination=caravan.ferry_uint32(QtBind.text(panel, dest_box).strip()))\n        caravan.ferry_validate_route(number, route)\n        routes = caravan.ferry_shared_routes((caravan.ferry_settings or {}).get('routes', {}))\n        routes[number] = route\n        caravan.ferry_validate_commands(routes)\n        caravan.ferry_write_shared_routes(routes)\n        caravan.ferry_settings['routes'] = routes\n        caravan.ferry_update_route_status()\n    except Exception as error:\n        status('Chưa lưu được: ' + str(error))\n        return\n    refresh()\n    status('Đã lưu phà %s · mã đích %s · dùng ngay cho tuyến buôn.' % (number, route['destination']))\n\ndef disconnected():\n    global armed, record, owner\n    armed, record, owner = False, None, None\n\nrefresh()\n")
_hh_load('rules', "import QtBind\npanel=QtBind.init(__name__,'Điều kiện Buôn phụ')\nQtBind.createLabel(panel,'Điều kiện Buôn phụ / đoàn đi cùng',8,169)\nQtBind.createLabel(panel,'Chờ sau khi Leader mua xong (giây)',8,193)\nwait_box=QtBind.createLineEdit(panel,'20',250,189,65,18)\nQtBind.createLabel(panel,'Bán kính nhập lại đội (m)',8,218)\njoin_box=QtBind.createLineEdit(panel,'10',250,214,65,18)\nQtBind.createLabel(panel,'Chờ xác nhận Bảo tiêu (giây)',390,236)\nrole_box=QtBind.createLineEdit(panel,'15',650,232,65,18)\nQtBind.createLabel(panel,'BT bị kẹt:',390,260)\naction_box=QtBind.createCombobox(panel,465,254,263,21)\noptions={'Dừng tại chỗ':'stop','VE BT → 20s → CUOI BT → tọa độ Leader':'bt','VE các acc trong đoàn (giữ hàng)':'team'}\nfor text in options:QtBind.append(panel,action_box,text)\n\ndef apply_values(values):\n    for field,key in ((wait_box,'departure_wait'),(join_box,'rejoin_radius'),(role_box,'escort_role_wait')):\n        QtBind.setText(panel,field,str(values[key]))\n    QtBind.setText(panel,action_box,next(text for text,code in options.items() if code==values['escort_missing_action']))\n\ndef export_values():\n    if not QtBind.isChecked(panel,caravan.follower_check) or QtBind.isChecked(panel,caravan.hunter_check):\n        return dict(caravan.convoy_rules_values)\n    return {'departure_wait':QtBind.text(panel,wait_box).strip(),'rejoin_radius':QtBind.text(panel,join_box).strip(),\n        'escort_role_wait':QtBind.text(panel,role_box).strip(),'escort_missing_action':options.get(QtBind.text(panel,action_box),'invalid')}\n\ncaravan.rules_panel=__import__('sys').modules[__name__]\napply_values(caravan.convoy_rules_values)\n")
_hh_load('schedule', "import base64\nimport hashlib\nimport json\nimport math\nimport os\nimport tempfile\nimport struct\nimport time\nimport uuid\nfrom datetime import datetime, timedelta\nimport QtBind\nimport phBot as bot\n\ngui=QtBind.init(__name__,'Hẹn giờ buôn')\nQtBind.createLabel(gui,'Hẹn giờ · giờ máy chạy phBot',12,34)\nQtBind.createLabel(gui,'Ngày bắt đầu',12,61)\ndate_box=QtBind.createLineEdit(gui,'',105,57,110,20)\nQtBind.createButton(gui,'scan_date','Quét ngày',225,56)\nQtBind.createLabel(gui,'Bắt đầu',12,85)\nstart_box=QtBind.createLineEdit(gui,'',82,81,80,20)\nQtBind.createLabel(gui,'Kết thúc',175,85)\nend_box=QtBind.createLineEdit(gui,'',245,81,80,20)\nQtBind.createButton(gui,'today','Hiện tại + 1 phút',12,106)\nrepeat_box=QtBind.createCheckBox(gui,'changed','Tự lặp chuyến trong khung giờ',12,133)\nQtBind.setChecked(gui,repeat_box,True)\nQtBind.createButton(gui,'arm','Lưu / Bật hẹn giờ',12,156)\nenabled_box=QtBind.createCheckBox(gui,'indicator_changed','Đã bật',140,158)\nif hasattr(QtBind,'setEnabled'):QtBind.setEnabled(gui,enabled_box,False)\nQtBind.createButton(gui,'cancel','Hủy hẹn giờ',236,156)\nroute_label=QtBind.createLineEdit(gui,'Hướng đang tích',12,184,315,18)\nplanned_label=QtBind.createLineEdit(gui,'Lịch: chưa đặt.',12,206,315,18)\nactual_label=QtBind.createLineEdit(gui,'Thực chạy: chưa bắt đầu.',12,228,315,18)\nend_label=QtBind.createLineEdit(gui,'Kết thúc chưa có.',12,250,315,18)\nstate_label=QtBind.createLineEdit(gui,'Lãi = tiền thu bán − vốn mua hàng; tính từ xuất phát đến bán xong.',12,276,715,18)\nteam_label=state_label\n# Compact meter next to the scheduling controls; no additional tab.\ngold_label=QtBind.createLineEdit(gui,'Vàng đang có: chưa đọc',345,34,383,18)\ncount_label=QtBind.createLineEdit(gui,'Đã xong: 0 chuyến',345,58,383,18)\nprofit_label=QtBind.createLineEdit(gui,'Tổng lãi đã ghi: 0',345,82,383,18)\ncurrent_label=QtBind.createLineEdit(gui,'Đang đi: chưa có',345,106,383,18)\ntrip_table=QtBind.createList(gui,345,132,383,105)\nQtBind.createButton(gui,'reset_metrics','Xóa số liệu',345,243)\nQtBind.createButton(gui,'scan_bag_gold','Quét túi / Vàng',450,243)\nbag_scan_label=QtBind.createLineEdit(gui,'Túi: chưa quét',575,245,153,18)\nowner=None\nplan=None\nremote=None\nlast_tick=0.\npre_error_at=0.\ncheckpoint_at=0.\nreturn_proof=None\nreturn_attempt=None\nMONO=time.monotonic\nWALL=time.time\n\n# Statistics live in the existing Hẹn giờ page and the same per-character JSON.\nfrom threading import RLock\nmeter_lock=RLock()\nmeter_error_at=0.\n\ndef meter_guarded(function):\n    def locked(*args,**kwargs):\n        with meter_lock:return function(*args,**kwargs)\n    return locked\n\nmetrics={'count':0,'seconds':0.,'profit':0,'known_profit':0,'history':[],'pending':{},'active':None}\n\n\ndef scan_bag_gold():\n    try:\n        if not key():\n            QtBind.setText(gui,gold_label,'Vàng đang có: chưa vào game')\n            QtBind.setText(gui,bag_scan_label,'Chưa vào game')\n            notice('Chưa vào game: không có dữ liệu vàng/túi mới.');return\n        inventory=bot.get_inventory()\n        value=gold()\n        meter_render()  # display refresh only: never mutate capital/profit/statistics\n        if not isinstance(inventory,dict) or not isinstance(inventory.get('items'),list) or len(inventory['items'])<13:\n            QtBind.setText(gui,bag_scan_label,'Chưa đọc được túi')\n            notice('Quét vàng: '+money(value)+'; phBot chưa trả đủ dữ liệu túi.');return\n        items=inventory['items'][13:]\n        used=sum(bool(item) for item in items);free=len(items)-used\n        QtBind.setText(gui,bag_scan_label,'Trống: {}/{}'.format(free,len(items)))\n        notice('Đã quét '+datetime.now().strftime('%H:%M:%S')+' | vàng: '+money(value)+' | túi: dùng {}, trống {} / {} ô (không tính trang bị).'.format(used,free,len(items)))\n    except Exception as error:\n        QtBind.setText(gui,bag_scan_label,'Lỗi đọc túi/vàng')\n        notice('Quét túi/vàng chưa được: '+str(error))\n\n\ndef gold():\n    value=(bot.get_character_data() or {}).get('gold')\n    if isinstance(value,bool):return None\n    try:\n        value=int(value)\n        return value if value>=0 else None\n    except (ValueError,TypeError,OverflowError):return None\n\ndef money(value):return format(int(value),',').replace(',','.') if value is not None else 'chưa đủ dữ liệu'\n\ndef minutes(value):\n    value=max(0,int(value));m,s=divmod(value,60)\n    return str(m)+'p'+(str(s).zfill(2)+'s' if s else '')\n\ndef meter_route():\n    points=[]\n    for line in (caravan.trip_lines or []):\n        point=caravan.walk_point(line)\n        if point is not None:points.append(point)\n    known=(('TA',6526.,1008.),('ĐH',3489.,2083.),('HĐ',149.,83.),('Dịch Chỉ',-1134.,2457.))\n    def city(point):\n        for name,x,y in known:\n            if math.hypot(point[0]-x,point[1]-y)<=100:return name\n        return None\n    if points:\n        source,destination=city(points[0]),city(points[-1])\n        if source and destination:return source+' → '+destination\n    return os.path.basename((caravan.trip or {}).get('path') or 'Tuyến đang chọn')\n\ndef meter_allowed():\n    return bool(key() and caravan.config and not caravan.config.get('hunter'))\n\n@meter_guarded\ndef meter_event(action,context=None):\n    sync()\n    if not meter_allowed():return\n    context=context or {}\n    if action=='trade_begin':\n        meter_finish(force=True)  # settle the last sale before a new order can spend gold\n        operation=context.get('meter_operation');token=context.get('native_token')\n        for previous in metrics['pending'].values():\n            previous['frozen']=True\n            if not previous.get('done'):previous['obsolete']=True\n        if operation=='buy' and token:\n            metrics['pending'][token]={'before':gold(),'after':None,'done':False,'at':WALL()}\n            # A failed order never accumulates without limit across retries.\n            while len(metrics['pending'])>16:metrics['pending'].pop(next(iter(metrics['pending'])))\n        elif operation=='sell' and metrics.get('active'):\n            metrics['active']['sale']={'token':token,'before':gold()}\n        save()\n    elif action=='trade_done' and context.get('meter_operation')=='buy':\n        part=metrics['pending'].get(context.get('native_token'))\n        if part:\n            part.update(after=gold(),done=True,done_mono=MONO(),stable_mono=MONO());save()\n    elif action=='depart':\n        meter_finish(force=True)\n        if metrics.get('active'):return  # GO/Trace retry is the same cargo journey\n        parts=[p for p in metrics['pending'].values() if p.get('done') and not p.get('obsolete')]\n        valid=bool(parts) and all(p.get('before') is not None and p.get('after') is not None and p['before']>=p['after'] for p in parts)\n        capital=sum(p['before']-p['after'] for p in parts) if valid else None\n        metrics['active']={'id':uuid.uuid4().hex,'start':WALL(),'route':meter_route(),'capital':capital,'sale':None}\n        metrics['pending']={};save()\n    elif action=='sold':\n        current=metrics.get('active')\n        if not current or current.get('finish') or not caravan.schedule_sale_confirmed:return\n        sale=current.get('sale') or {}\n        current['finish']={'end':WALL(),'before':sale.get('before'),'after':gold(),'stable_mono':MONO()}\n        save()\n    meter_render()\n\n@meter_guarded\ndef meter_tick():\n    now=MONO()\n    # Native completion can precede the final character-gold update by one callback.\n    for part in metrics['pending'].values():\n        if part.get('done') and not part.get('frozen') and now-part.get('done_mono',now)<=3:\n            value=gold()\n            if value!=part.get('after'):\n                part.update(after=value,stable_mono=now)\n    meter_finish()\n    meter_render()\n\n@meter_guarded\ndef meter_finish(force=False):\n    current=metrics.get('active')\n    if not current or not current.get('finish'):return\n    finish=current['finish'];value=gold()\n    if not finish.get('restored') and value!=finish.get('after'):\n        finish.update(after=value,stable_mono=MONO())\n    if not force and MONO()-finish.get('stable_mono',MONO())<1:return\n    seconds=max(0.,finish['end']-current['start'])\n    before,after=finish.get('before'),finish.get('after')\n    revenue=after-before if before is not None and after is not None and after>=before else None\n    capital=current.get('capital')\n    profit=revenue-capital if revenue is not None and capital is not None else None\n    number=metrics['count']+1\n    metrics['history'].append({'number':number,'id':current['id'],'route':current['route'],'start':current['start'],\n        'end':finish['end'],'seconds':seconds,'capital':capital,'revenue':revenue,'profit':profit})\n    metrics['history']=metrics['history'][-200:]\n    metrics['count']=number;metrics['seconds']+=seconds\n    if profit is not None:\n        metrics['profit']+=profit;metrics['known_profit']+=1\n    metrics['active']=None;save()\n\n@meter_guarded\ndef reset_metrics():\n    global metrics\n    sync()\n    if metrics.get('active') or (caravan.active and metrics.get('pending')):\n        notice('Đang đo một chuyến: bán xong rồi mới xóa số liệu.');return\n    metrics={'count':0,'seconds':0.,'profit':0,'known_profit':0,'history':[],'pending':{},'active':None}\n    save();meter_render();notice('Đã xóa thống kê trên acc này, không đổi tuyến/hẹn giờ.')\n\n@meter_guarded\ndef meter_render():\n    QtBind.setText(gui,gold_label,'Vàng đang có: '+money(gold()))\n    count=metrics['count'];average=metrics['seconds']/count if count else 0.\n    QtBind.setText(gui,count_label,'Đã xong: {} chuyến · TB: {}/chuyến'.format(count,minutes(average)))\n    QtBind.setText(gui,profit_label,'Tổng lãi đã ghi: '+money(metrics['profit'])+' · {}/{} chuyến'.format(metrics['known_profit'],count))\n    current=metrics.get('active')\n    text='Đang đi: '+current['route']+' · '+minutes(WALL()-current['start']) if current and not current.get('finish') else 'Chỉ tính chuyến khi xác nhận bán hết hàng.'\n    QtBind.setText(gui,current_label,text)\n    QtBind.clear(gui,trip_table)\n    for row in reversed(metrics['history']):\n        text='Chuyến {} | {} | {} | Lãi: {}'.format(row['number'],row['route'],minutes(row['seconds']),money(row['profit']))\n        if row['profit'] is None:text+=' (chưa ghi đủ vốn/thu)'\n        QtBind.append(gui,trip_table,text)\n\n\ndef meter_safe_tick():\n    global meter_error_at\n    try:meter_tick()\n    except Exception as error:\n        if MONO()-meter_error_at>=30:\n            meter_error_at=MONO()\n            notice('Thống kê tạm chưa đọc được; lịch buôn vẫn xử lý: '+str(error))\n\n\n# Conservative known in-town trading points from the supplied caravan scripts.\nTOWN_POINTS=(('Trường An',6526.,1008.,0.),('Đôn Hoàng',3489.,2083.,-106.),('Hòa Điền',149.,83.,243.))\n\ndef changed(_checked): pass\n\ndef indicator_changed(_checked):pass\n\ndef scan_date():\n    QtBind.setText(gui,date_box,datetime.now().strftime('%d/%m/%Y'))\n\ndef today():\n    now=datetime.now()+timedelta(minutes=1)\n    QtBind.setText(gui,date_box,now.strftime('%d/%m/%Y'))\n    QtBind.setText(gui,start_box,now.strftime('%H:%M'))\n    QtBind.setText(gui,end_box,(now+timedelta(hours=8)).strftime('%H:%M'))\n\ndef key():\n    row=bot.get_character_data() or {}\n    return (str(row.get('server') or ''),str(row.get('name'))) if row.get('name') else None\n\ndef path():\n    digest=hashlib.sha256(json.dumps(owner,ensure_ascii=False).encode()).hexdigest()\n    return os.path.join(bot.get_config_dir(),'CaravanRoutes','Schedule',digest+'.json')\n\n@meter_guarded\ndef save():\n    if not owner:return\n    filename=path();os.makedirs(os.path.dirname(filename),exist_ok=True)\n    temporary=None\n    try:\n        with tempfile.NamedTemporaryFile('w',encoding='utf-8',dir=os.path.dirname(filename),delete=False) as f:\n            temporary=f.name;json.dump({'owner':list(owner),'plan':plan,'remote':remote,'town_proof':return_proof,'metrics':metrics},f,ensure_ascii=False,indent=2)\n        os.replace(temporary,filename)\n    finally:\n        if temporary and os.path.exists(temporary):os.remove(temporary)\n\ndef notice(message):\n    QtBind.setText(gui,state_label,message)\n    bot.log('[Hẹn giờ buôn] '+message)\n\n@meter_guarded\ndef sync():\n    global owner,plan,remote,return_proof,return_attempt,metrics\n    current=key()\n    if not current or current==owner:return\n    owner=current;plan=remote=return_proof=return_attempt=None\n    metrics={'count':0,'seconds':0.,'profit':0,'known_profit':0,'history':[],'pending':{},'active':None}\n    caravan.schedule_draining=False;caravan.schedule_hold=False\n    try:\n        with open(path(),encoding='utf-8') as f:data=json.load(f)\n        if data.get('owner')!=list(owner):raise ValueError('Sai nhân vật của lịch')\n        plan=data.get('plan');remote=data.get('remote')\n        for record in (plan,remote):\n            if record is None:continue\n            if not isinstance(record,dict) or not isinstance(record.get('token'),str) or len(record['token'])!=16:\n                raise ValueError('Cấu trúc lịch không hợp lệ')\n            if record.get('phase') not in ('waiting','starting','running','blocked','draining','parking','parked','done','cancelled'):\n                raise ValueError('Trạng thái lịch không hợp lệ')\n            if not isinstance(record.get('end'),(float,int)) or not math.isfinite(record['end']):\n                raise ValueError('Giờ kết thúc không hợp lệ')\n            record.pop('empty_at',None);record.pop('retry_at',None)\n        if plan and (not isinstance(plan.get('start'),(int,float)) or not isinstance(plan.get('route'),dict)):\n            raise ValueError('Thiếu giờ bắt đầu/hướng buôn')\n        if plan and not all(isinstance(plan['route'].get(k),str) for k in ('slot','path','digest')):\n            raise ValueError('Hướng buôn lưu không hợp lệ')\n        if remote and (not isinstance(remote.get('leader'),str) or not remote['leader']):\n            raise ValueError('Thiếu Leader của lịch')\n        stored=data.get('metrics')\n        if isinstance(stored,dict):\n            for k in ('count','seconds','profit','known_profit','history','pending','active'):\n                if k in stored:metrics[k]=stored[k]\n            if (not isinstance(metrics['history'],list) or not isinstance(metrics['pending'],dict)\n                    or not all(isinstance(metrics[k],(int,float)) for k in ('count','seconds','profit','known_profit'))\n                    or not all(isinstance(p,dict) for p in metrics['pending'].values())\n                    or (metrics['active'] is not None and not isinstance(metrics['active'],dict))):\n                metrics={'count':0,'seconds':0.,'profit':0,'known_profit':0,'history':[],'pending':{},'active':None}\n                notice('Thống kê cũ không hợp lệ; giữ nguyên lịch, bắt đầu bộ đếm mới.')\n            for part in metrics['pending'].values():\n                part['done_mono']=MONO()-10;part.pop('stable_mono',None)\n            if metrics.get('active') and metrics['active'].get('finish'):\n                metrics['active']['finish']['stable_mono']=MONO()\n                metrics['active']['finish']['restored']=True\n        proof=data.get('town_proof')\n        if isinstance(proof,dict) and proof.get('owner')==list(owner):return_proof=proof\n        for record in (plan,remote):\n            if record and record.get('phase') not in ('waiting','done','cancelled'):\n                record['interrupted']=True\n                record.pop('empty_at',None)\n                record['had_goods']=True\n                record['cargo_cleared']=False\n                record['status']='Phiên đã gián đoạn; không tự mua/chạy lại. Có thể GO để tiếp tục hàng cũ.'\n    except FileNotFoundError:pass\n    except (ValueError,OSError,TypeError) as error:\n        plan=remote=None;notice('Không đọc được lịch: '+str(error))\n    if plan:\n        QtBind.setText(gui,date_box,datetime.fromtimestamp(plan['start']).strftime('%d/%m/%Y'))\n        QtBind.setText(gui,start_box,datetime.fromtimestamp(plan['start']).strftime('%H:%M:%S'))\n        QtBind.setText(gui,end_box,datetime.fromtimestamp(plan['end']).strftime('%H:%M:%S'))\n        QtBind.setChecked(gui,repeat_box,bool(plan.get('repeat')))\n\n\ndef clock_time(text):\n    for fmt in ('%H:%M:%S','%H:%M'):\n        try:return datetime.strptime(text.strip(),fmt).time()\n        except ValueError:pass\n    raise ValueError('Giờ phải là HH:MM hoặc HH:MM:SS')\n\ndef window(date_text,start_text,end_text):\n    day=datetime.strptime(date_text.strip(),'%d/%m/%Y').date()\n    start=datetime.combine(day,clock_time(start_text));end=datetime.combine(day,clock_time(end_text))\n    if end<=start:end+=timedelta(days=1)\n    return start.timestamp(),end.timestamp()\n\ndef route_snapshot():\n    if not caravan.config or caravan.config.get('hunter') or caravan.config.get('follower'):\n        raise ValueError('Chỉ Leader buôn chính được đặt lịch cả đoàn')\n    if not caravan.own_names() & caravan.names(caravan.config.get('leaders','')):\n        raise ValueError('Acc này chưa nằm trong danh sách Leader đã lưu')\n    selected=caravan.route_selected\n    if not selected:raise ValueError('Tích một hướng buôn trước khi lưu lịch')\n    filename=caravan.selected_script_path()\n    with open(filename,encoding='utf-8-sig') as f:content=f.read()\n    return {'slot':selected,'path':filename,'digest':hashlib.sha256(content.encode()).hexdigest()}\n\ndef arm():\n    global plan\n    try:\n        sync();caravan.load_identity()\n        if remote and remote.get('phase') not in ('done','cancelled'):raise ValueError('Acc đang nhận lịch từ Leader khác')\n        if plan and plan.get('phase') not in ('waiting','done','cancelled'):raise ValueError('Phiên đang chạy/gia hạn; chưa thay lịch')\n        start,end=window(QtBind.text(gui,date_box),QtBind.text(gui,start_box),QtBind.text(gui,end_box))\n        if end<=WALL():raise ValueError('Giờ kết thúc đã qua')\n        route=route_snapshot()\n        if not caravan.config.get('finish_come') and not caravan.selected_has_turnaround():\n            raise ValueError('Bật Bán cả đội hoặc chọn tuyến có turnaround để xác nhận bán/về thành theo lịch')\n        previous=plan\n        plan={'token':uuid.uuid4().hex[:16],'phase':'waiting','start':start,'end':end,'route':route,\n              'repeat':QtBind.isChecked(gui,repeat_box),'actual_start':None,'actual_end':None,'run_seconds':0.,\n              'ready':[],'safe':{},'roster':{},'next_send':0.,'status':'Đã bật hẹn giờ.'}\n        try:save()\n        except Exception:plan=previous;raise\n        notice('Đã lưu lịch. Hết giờ sẽ gia hạn tới khi cả đoàn ở trong thành, không mua chuyến mới.')\n    except (ValueError,OSError,TypeError,KeyError) as error:notice('Chưa bật lịch: '+str(error))\n    render()\n\ndef cancel():\n    global plan,remote\n    sync()\n    if (plan and plan.get('phase') in ('draining','parking')) or (remote and remote.get('phase') in ('draining','parking','parked')):\n        notice('Đang kết thúc có hàng: tiếp tục đưa đoàn vào thành, chưa hủy bảo vệ hàng.');return\n    if plan:\n        if plan.get('phase') in ('starting','running','blocked'):\n            send_all(plan,'CANCEL')\n        plan['phase']='cancelled';save()\n    caravan.schedule_draining=False;caravan.schedule_hold=False\n    notice('Đã hủy hẹn giờ; không dừng tuyến buôn đang chạy.')\n\ndef enc(name):return base64.b64encode(name.encode()).decode('ascii')\n\ndef send(name,record,action):\n    suffix=(' '+str(int(record['end']))) if action.startswith('START') else ''\n    message='!CRTIME {} {}{} {}'.format(record['token'],action,suffix,enc(name))\n    if len(message)>120:raise ValueError('Tên nhận lệnh quá dài')\n    return caravan.control_party(message)\n\ndef send_all(record,action):\n    for name in record['roster']:\n        if not send(name,record,action):return False\n    return True\n\ndef busy():\n    if caravan.ferry_transaction_hold():return True\n    if caravan.time.monotonic()<caravan.ferry_transport_grace:return True\n    for name in ('follower_state','finish_context','recovery','return_request','route_crossing','ferry_pending',\n                 'bt_recall','escort_recall','guard_call','buy_departure'):\n        if getattr(caravan,name,None):return True\n    if (caravan.trip or {}).get('recovery_pending'):return True\n    sale=caravan.local_sale\n    if sale and not (caravan.completed_sale and caravan.completed_sale.get('batch')==sale.get('batch')):return True\n    if caravan.convoy_controller:return True\n    step=caravan.merchant_step\n    if step and not step.get('direct'):return True\n    return False\n\ndef cargo(record=None):\n    # Unknown is not empty; never send Return/mark safe based on a missing inventory API.\n    pet=caravan.finish_transport()\n    if pet is None:\n        if record and record.get('had_goods') and not (record.get('cargo_cleared') or caravan.schedule_sale_confirmed):\n            raise ValueError('Thú biến mất khi đã có hàng; chưa xác nhận bán hết/thu hồi hàng')\n        return 0\n    count=caravan.transport_goods(pet)\n    if record is not None:\n        if count>0:\n            record['had_goods']=True;record['cargo_cleared']=False\n        elif caravan.schedule_sale_confirmed:\n            record['cargo_cleared']=True\n    return count\n\ndef town():\n    global return_proof\n    row=bot.get_character_data() or {}\n    if row.get('dead') or not row.get('name'):return None\n    try:\n        x,y,z=float(row['x']),float(row['y']),float(row.get('z') or 0)\n        if not all(math.isfinite(v) for v in (x,y,z)):return None\n        for name,tx,ty,tz in TOWN_POINTS:\n            if math.hypot(x-tx,y-ty)<=30 and abs(z-tz)<=30 and 0<int(row['region'])<32768:return name\n        if return_proof and return_proof['owner']==list(owner) and row['region']==return_proof['region']:\n            if math.hypot(x-return_proof['x'],y-return_proof['y'])<=30:return 'thành sau bùa về'\n    except (KeyError,ValueError,TypeError):return None\n    return None\n\ndef finish_here(record):\n    global return_attempt\n    if busy() or not caravan.config:return False\n    row=bot.get_character_data() or {}\n    if row.get('dead') or not row.get('name'):return False\n    goods=cargo(record);city=town()\n    if goods:\n        record.pop('empty_at',None)\n        if city and not record.get('sale_attempted') and not caravan.trade_fault:\n            record['sale_attempted']=True;save()\n            caravan.start_party_trade('BAN',row['name'])\n            record['status']='Đã vào '+city+'; đang bán nốt hàng, chưa kết thúc.'\n        else:record['status']='Đang gia hạn: còn hàng; tiếp tục tuyến/Trace tới thành để bán.'\n        return False\n    if not city:\n        record.pop('empty_at',None)\n        if not return_attempt and not record.get('return_attempted') and not caravan.trade_fault:\n            origin=caravan.snapshot_position(row)\n            if not origin:return False\n            record['return_attempted']=True;save()\n            return_attempt={'owner':list(owner),'origin':origin,'requested':MONO(),'spawn':False}\n            caravan.queue_return()\n        record['status']='Đang gia hạn: hết hàng, chờ xác nhận bùa về thành.'\n        return False\n    now=MONO()\n    record.setdefault('empty_at',now)\n    if now-record['empty_at']<2:return False\n    if not record.get('parked'):\n        caravan.local_stop();bot.stop_bot()\n        caravan.schedule_draining=True;caravan.schedule_hold=True\n        record['parked']=True;record['city']=city;save()\n    record['status']='Đã bán hết, đứng trong '+city+'.'\n    return True\n\ndef begin_drain(record):\n    if record['phase'] not in ('draining','parking','parked'):\n        record['phase']='draining';record['drain_at']=WALL();record['next_send']=0.\n        record.pop('empty_at',None);save()\n    caravan.schedule_draining=True;caravan.set_loop(False)\n\ndef _pre_tick():\n    # Caravan's original loop loads identity once; do not add an early load during a ferry.\n    sync()\n    active_record=plan if plan and plan.get('phase') not in ('done','cancelled') else remote\n    if not active_record or active_record.get('phase') in ('done','cancelled'):return\n    if WALL()>=active_record['end']:\n        if active_record['phase']=='waiting':\n            active_record['phase']='cancelled';active_record['status']='Đã quá khung giờ, chưa bắt đầu nên không chạy bù.';save()\n            return\n        begin_drain(active_record)\n    if active_record.get('parked'):\n        caravan.schedule_hold=True\n\n\ndef pre_tick():\n    global pre_error_at\n    try:_pre_tick()\n    except Exception as error:\n        caravan.schedule_draining=True\n        caravan.set_loop(False)\n        if MONO()-pre_error_at>=15:\n            pre_error_at=MONO();notice('Lỗi lịch, chưa mở chuyến mới: '+str(error))\n\n\ndef prepare_start():\n    caravan.load_identity()\n    snapshot=route_snapshot()\n    if snapshot!=plan['route']:raise ValueError('Hướng/TXT đã thay đổi sau khi lưu lịch; hủy lịch rồi lưu lại')\n    if not caravan.config.get('finish_come') and not caravan.selected_has_turnaround():\n        raise ValueError('Cần Bán cả đội/tuyến turnaround để kết thúc trong thành')\n    roster=caravan.convoy_roster()\n    wanted=caravan.names(caravan.config.get('guards',''))-caravan.own_names()\n    found=set().union(*(r['aliases'] for r in roster.values())) if roster else set()\n    if wanted-found:raise ValueError('Chờ thành viên đoàn vào Party: '+', '.join(sorted(wanted-found)))\n    if not bot.get_party() or not roster:raise ValueError('Chờ đủ Party và thành viên đoàn')\n    with open(snapshot['path'],encoding='utf-8-sig') as f:\n        lines=[line.strip() for line in f if line.strip() and not line.lstrip().startswith(('#','//'))]\n    caravan.ferry_event_loop();caravan.validate_route_ferry_steps(lines)\n    plan['roster']={r['canonical']:{} for r in roster.values()}\n    plan['phase']='starting';plan['status']='Chờ các acc xác nhận lịch; chưa mua hàng.';plan['next_send']=0.\n    save()\n\ndef start_once():\n    if plan.get('fired'):return\n    plan['fired']=True;plan['actual_start']=WALL();save()  # write before dispatch: never replay buys on reload\n    caravan.enable_following();caravan.set_loop(bool(plan['repeat']))\n    if not caravan.active:\n        if cargo()>0:caravan.execute('GO')\n        else:caravan.start_new_trip_now()\n    plan['phase']='running' if caravan.active else 'blocked'\n    plan['status']='Đang buôn theo hướng đã lưu.' if caravan.active else 'Chưa khởi chạy được; xem Log. Không tự gửi mua lại.'\n    save()\n\ndef handle_chat(channel,player,message):\n    global remote\n    if not isinstance(message,str) or not message.startswith('!CRTIME '):return\n    sync();caravan.load_identity()\n    if channel!=4 or not caravan.config or not isinstance(player,str) or not caravan.party_member(player):return\n    fields=message.split()\n    if len(fields) not in (4,5) or len(fields[1])!=16 or any(x not in '0123456789abcdef' for x in fields[1]):return\n    token,action=fields[1:3]\n    if not caravan.convoy_target_is_me(fields[-1]):return\n    member=caravan.resolve_follow_target(player)\n    sender=caravan.norm(member.get('name') or player) if member else caravan.norm(player)\n    if action in ('READY','SAFE','DONE'):\n        if not plan or token!=plan['token'] or sender not in plan.get('roster',{}):return\n        if action=='READY' and plan['phase']=='starting':\n            if sender not in plan['ready']:plan['ready'].append(sender);save()\n        elif action=='SAFE' and plan['phase'] in ('draining','parking'):\n            plan['safe'][sender]=WALL()\n        elif action=='DONE' and plan['phase']=='done':\n            if sender not in plan.setdefault('finished',[]):plan['finished'].append(sender);save()\n        return\n    if not caravan.trusted_leader(player) or not (caravan.config.get('hunter') or caravan.config.get('follower')):return\n    if action.startswith('START'):\n        if action not in ('START0','START1') or len(fields)!=5:return\n        try:end=float(fields[3]);assert math.isfinite(end) and end>WALL()\n        except (ValueError,AssertionError):return\n        if remote and remote.get('phase') not in ('done','cancelled') and remote['token']!=token:\n            if not (remote.get('parked') and remote['leader']==sender and town() and cargo(remote)==0 and not busy()):return\n        if not remote or remote['token']!=token:\n            remote={'token':token,'leader':sender,'phase':'running','end':end,'actual_start':WALL(),\n                    'actual_end':None,'next_send':0.,'status':'Đã nhận lịch từ '+player}\n            save();caravan.schedule_draining=False;caravan.schedule_hold=False\n            caravan.enable_following();caravan.set_loop(action=='START1')\n            if caravan.config.get('hunter') and not busy():caravan.start_follow_target(player)\n        send(sender,remote,'READY');return\n    if not remote or remote['token']!=token or remote['leader']!=sender:return\n    if action=='CANCEL':\n        remote['phase']='cancelled';caravan.schedule_draining=False;caravan.schedule_hold=False;save()\n    elif action=='DRAIN':begin_drain(remote)\n    elif action=='PARK':\n        begin_drain(remote);remote['park_requested']=True;save()\n    elif action=='FINAL' and remote.get('parked'):\n        # Re-check current town/cargo, not an old SAFE acknowledgement.\n        if town() and cargo(remote)==0 and not busy():\n            remote['phase']='done';remote['actual_end']=WALL();remote['status']='Đã kết thúc trong thành, hết hàng.';save()\n            caravan.schedule_draining=False;caravan.schedule_hold=False\n            send(sender,remote,'DONE')\n\n\ndef event_loop():\n    global last_tick,checkpoint_at,return_proof\n    pre_tick()\n    if MONO()-last_tick<0.5:return\n    meter_safe_tick()\n    elapsed=max(0,min(2.,MONO()-last_tick)) if last_tick else 0.\n    last_tick=MONO()\n    if return_attempt and return_attempt.get('spawn') and caravan.last_return>=return_attempt['requested']:\n        row=bot.get_character_data() or {};origin=return_attempt['origin']\n        pos=caravan.snapshot_position(row)\n        if pos and (pos['region']!=origin['region'] or math.hypot(pos['x']-origin['x'],pos['y']-origin['y'])>30):\n            return_proof=dict(pos,owner=list(owner))\n    try:\n        if plan and plan['phase']=='waiting' and WALL()>=plan['start'] and WALL()<plan['end']:\n            if not plan.get('interrupted') and MONO()>=plan.get('retry_at',0):\n                plan['retry_at']=MONO()+5\n                try:prepare_start()\n                except (ValueError,OSError,TypeError) as error:plan['status']='Chờ bắt đầu: '+str(error)\n        if plan and plan['phase']=='starting' and not plan.get('interrupted'):\n            if set(plan['roster'])<=set(plan['ready']):start_once()\n            elif WALL()>=plan['next_send']:\n                plan['next_send']=WALL()+5;send_all(plan,'START1' if plan['repeat'] else 'START0')\n        if plan and plan.get('actual_start') and plan['phase'] not in ('done','cancelled'):\n            cargo(plan)\n            if caravan.active and not plan.get('parked'):plan['run_seconds']+=elapsed\n        if plan and plan['phase'] in ('draining','parking'):\n            if WALL()>=plan['next_send']:\n                plan['next_send']=WALL()+5;send_all(plan,'PARK' if plan.get('parked') else 'DRAIN')\n            if finish_here(plan):\n                plan['phase']='parking'\n                safe={name for name,at in plan['safe'].items() if WALL()-at<=6}\n                if set(plan['roster'])<=safe:\n                    if send_all(plan,'FINAL'):\n                        plan['phase']='done';plan['actual_end']=WALL();plan['status']='Đã kết thúc: cả đoàn trong thành, hết hàng.';save()\n                        caravan.schedule_draining=False;caravan.schedule_hold=False\n                        notice('Đã kết thúc: Leader và các acc trong đoàn đều xác nhận trong thành, hết hàng.')\n        if plan and plan['phase']=='done' and WALL()-plan.get('actual_end',0)<60 and WALL()>=plan['next_send']:\n            plan['next_send']=WALL()+5\n            if set(plan['roster'])-set(plan.get('finished',[])):send_all(plan,'FINAL')\n        if remote and remote.get('actual_start') and remote['phase'] not in ('done','cancelled'):\n            cargo(remote)\n            if caravan.active and not remote.get('parked'):remote['run_seconds']=remote.get('run_seconds',0)+elapsed\n        if remote and remote['phase'] in ('draining','parking','parked') and remote.get('park_requested'):\n            if finish_here(remote) and WALL()>=remote['next_send']:\n                remote['next_send']=WALL()+2;remote['phase']='parked';send(remote['leader'],remote,'SAFE')\n        if MONO()-checkpoint_at>=30 and (plan or remote):checkpoint_at=MONO();save()\n    except (ValueError,OSError,TypeError,KeyError) as error:\n        record=plan or remote\n        if record:record['status']='Chưa kết thúc an toàn: '+str(error)\n    render()\n\ndef teleported():\n    if return_attempt:return_attempt['spawn']=True\n\ndef disconnected():\n    for record in (plan,remote):\n        if record and record.get('phase') not in ('waiting','done','cancelled'):\n            record['interrupted']=True;record['status']='Mất kết nối; không tự mua/chạy lại. Hết giờ vẫn chờ kết thúc trong thành.'\n    save()\n\ndef duration(value):\n    seconds=max(0,int(value));return '{:02d}:{:02d}:{:02d}'.format(seconds//3600,seconds//60%60,seconds%60)\n\ndef stamp(value):return datetime.fromtimestamp(value).strftime('%d/%m %H:%M:%S') if value else 'chưa có'\n\ndef render():\n    record=plan or remote\n    QtBind.setChecked(gui,enabled_box,bool(record and record.get('phase') not in ('done','cancelled')))\n    if not record:\n        QtBind.setText(gui,route_label,'Hướng đang tích')\n        QtBind.setText(gui,planned_label,'Lịch: chưa đặt.')\n        QtBind.setText(gui,actual_label,'Thực chạy: chưa bắt đầu.')\n        QtBind.setText(gui,end_label,'Kết thúc chưa có.')\n        return\n    if plan:\n        QtBind.setText(gui,route_label,'Hướng: '+os.path.basename(plan['route']['path']))\n        QtBind.setText(gui,planned_label,'Dự kiến: '+stamp(plan['start'])+' → '+stamp(plan['end']))\n        QtBind.setText(gui,actual_label,'Bắt đầu '+stamp(plan.get('actual_start'))+' · chạy '+duration(plan.get('run_seconds',0)))\n    else:\n        QtBind.setText(gui,route_label,'Theo lịch Leader: '+remote['leader'])\n        QtBind.setText(gui,planned_label,'Kết thúc dự kiến: '+stamp(remote['end']))\n        QtBind.setText(gui,actual_label,'Bắt đầu '+stamp(remote.get('actual_start'))+' · chạy '+duration(remote.get('run_seconds',0)))\n    extra=max(0,(record.get('actual_end') or WALL())-record['end']) if record['phase'] in ('draining','parking','parked','done') else 0\n    QtBind.setText(gui,end_label,'Kết thúc '+stamp(record.get('actual_end'))+' · gia hạn '+duration(extra))\n    QtBind.setText(gui,state_label,record.get('status','')[:108])\n    if plan and plan['phase'] in ('draining','parking'):\n        waiting=[name for name in plan['roster'] if WALL()-plan['safe'].get(name,0)>6]\n        QtBind.setText(gui,team_label,record.get('status','')+' | Chờ trong thành: '+(', '.join(waiting) or 'Leader xác nhận'))\n\ncaravan.trip_meter=__import__('sys').modules[__name__]\ntoday()\nmeter_render()\n\n# Some phBot builds omit the sender in handle_chat; use the same server Party layout as caravan.\ndef handle_joymax(opcode,data):\n    if opcode!=0x3026 or not data or data[0]!=4:return True\n    try:\n        player,end=caravan.decode_control_chat_string(data,1)\n        message,end=caravan.decode_control_chat_string(data,end)\n        if end==len(data) and message.startswith('!CRTIME '):handle_chat(4,player,message)\n    except (ValueError,UnicodeError,TypeError,IndexError,struct.error):pass\n    return True\n")
