def _hh_dispatch(hook, *args):
    if not _hh_trade_gate():return True
    allowed = True
    for page, module in _hh_modules.items():
        callback = getattr(module, hook, None)
        if not callable(callback):
            continue
        try:
            if callback(*args) is False:
                allowed = False
        except Exception as error:
            # One engine must not prevent the other from receiving game events.
            now = _time.monotonic()
            key = (page, hook, str(error))
            if now - _hh_hook_errors.get(key, float('-inf')) >= 15:
                _hh_hook_errors[key] = now
                _hh_error_log('%s / %s: %s' % (page, hook, error),True)
    return allowed


def CaravanRoutesTradeDone(args):
    return _hh_caravan.CaravanRoutesTradeDone(args)


def CaravanRoutesFollowerLoaded(args):
    """Expose the original phBot script command from the embedded caravan engine."""
    return _hh_caravan.CaravanRoutesFollowerLoaded(args)


def event_loop():
    if not _hh_trade_gate():return
    _hh_modules['schedule'].pre_tick()
    _hh_dispatch('event_loop')


def handle_chat(t, player, msg):
    _hh_dispatch('handle_chat', t, player, msg)


def handle_event(t, data):
    _hh_dispatch('handle_event', t, data)


def handle_joymax(opcode, data):
    return _hh_dispatch('handle_joymax', opcode, data)


def handle_silkroad(opcode, data):
    return _hh_dispatch('handle_silkroad', opcode, data)


def teleported():
    _hh_dispatch('teleported')


def disconnected():
    _hh_dispatch('disconnected')


